use serde_json::json;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let input_cents = input["cents"].as_i64().unwrap();
    let pounds = input_cents / 100;
    let cents_remainder = input_cents % 100;
    let fractional_digits = format!("{:.2}", cents_remainder);
    let mut pounds_str = format!("{}.{}", pounds, fractional_digits);
    if pounds_str.starts_with("-") {
        pounds_str = "-".to_string() + &pounds_str;
    }
    json!(pounds_str)
}
